1→//! ChatService gRPC server implementation.
//!
//! Implements the `op_chat.chat.ChatService` trait from `chat.proto`.
//!
//! Architecture:
//! - threetched owns provider/model routing (OD-28) — SendRequest carries them.
//! - gemma_brain routes to the selected model and applies compliance tags.
//! - The chatbot is a DELEGATOR — forced tool calling is mandatory; even user
//!   responses are emitted as tool calls (respond_to_user).
10→//! - Chat persistence flows through the memory loop → cognitive.
//! - The agent loop is bounded (≥50 steps) and cancellable.

use std::pin::Pin;
use std::sync::Arc;

use tokio::sync::Mutex;
use tokio_stream::Stream;
use tokio_stream::wrappers::ReceiverStream;
use tonic::{Request, Response, Status};
20→use tracing::{info, warn};

use crate::orchestration::proto::op_chat_chat::{
    ApproveRequest, ApproveResponse, CancelRequest, CancelResponse, ChatFrame, Heartbeat,
    SendRequest, StreamDone, UiMessagePart, chat_frame, chat_service_server::ChatService,
};

/// Shared state for the ChatService.
pub struct ChatServiceImpl {
    /// Active conversation cursors for cancel support.
30→    cancellations: Arc<Mutex<std::collections::HashMap<String, tokio::sync::watch::Sender<bool>>>>,
    /// Pending approvals: tool_call_id -> oneshot sender.
    approvals: Arc<Mutex<std::collections::HashMap<String, tokio::sync::oneshot::Sender<bool>>>>,
}

impl ChatServiceImpl {
    pub fn new() -> Self {
        Self {
            cancellations: Arc::new(Mutex::new(Default::default())),
            approvals: Arc::new(Mutex::new(Default::default())),
40→        }
    }
}

impl Default for ChatServiceImpl {
    fn default() -> Self {
        Self::new()
    }
}

50→type ChatStream = Pin<Box<dyn Stream<Item = Result<ChatFrame, Status>> + Send + 'static>>;

#[async_trait::async_trait]
impl ChatService for ChatServiceImpl {
    type SendStream = ChatStream;

    async fn send(
        &self,
        request: Request<SendRequest>,
    ) -> Result<Response<Self::SendStream>, Status> {
60→        let req = request.into_inner();
        let conversation_id = req.conversation_id.clone();
        let provider = req.provider.clone();
        let model = req.model.clone();

        info!(
            conversation_id = %conversation_id,
            provider = %provider,
            model = %model,
            "ChatService.Send — streaming chat completion"
70→        );

        // Parse ui_messages from JSON bytes.
        let ui_messages: Vec<serde_json::Value> = serde_json::from_slice(&req.ui_messages)
            .map_err(|e| Status::invalid_argument(format!("Invalid ui_messages JSON: {e}")))?;

        // Set up cancellation channel.
        let (cancel_tx, _cancel_rx) = tokio::sync::watch::channel(false);
        {
            let mut cancellations = self.cancellations.lock().await;
80→            cancellations.insert(conversation_id.clone(), cancel_tx);
        }

        // Cursor for monotonic frame ordering.
        let cursor = std::sync::atomic::AtomicU64::new(0);

        let (tx, rx) = tokio::sync::mpsc::channel::<Result<ChatFrame, Status>>(64);

        let cancellations = self.cancellations.clone();
        let conv_id = conversation_id.clone();
90→
        tokio::spawn(async move {
            let bump = || cursor.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            // Emit heartbeat immediately so the client knows the stream is alive.
            let _ = tx
                .send(Ok(ChatFrame {
                    cursor: bump(),
                    body: Some(chat_frame::Body::Heartbeat(Heartbeat {
                        server_time_ms: chrono::Utc::now().timestamp_millis() as u64,
                    })),
100→                }))
                .await;

            // TODO: Wire to gemma_brain routing + ForcedToolPipeline.
            //
            // The pipeline will:
            // 1. Build ChatRequest with tool_choice: Required
            // 2. Route through gemma_brain to the selected provider/model
            // 3. For each ModelPart yielded:
            //    - Text → ChatFrame::Part(text)
110→            //    - ToolCall → ChatFrame::Part(tool-call) + ApprovalRequired if needed
            //    - ToolResult → ChatFrame::Part(tool-result)
            //    - Reasoning → ChatFrame::Part(reasoning)
            // 4. Feed completed transcript to MemoryLoop for persistence
            // 5. Bounded at ≥50 steps, cancellable via cancel_rx

            // Placeholder: echo back the last user message as a reasoning part
            // so the client can verify the stream is working.
            if let Some(last_msg) = ui_messages.last() {
                let role = last_msg
120→                    .get("role")
                    .and_then(|v| v.as_str())
                    .unwrap_or("user");
                let content = last_msg
                    .get("content")
                    .and_then(|v| v.as_str())
                    .unwrap_or("");

                let payload = serde_json::json!({
                    "type": "text",
130→                    "text": format!(
                        "[ChatService stub] Received message from {role} via {provider}/{model}. \
                         Delegation pipeline not yet wired. Message: {content}"
                    )
                });

                let _ = tx
                    .send(Ok(ChatFrame {
                        cursor: bump(),
                        body: Some(chat_frame::Body::Part(UiMessagePart {
140→                            message_id: uuid::Uuid::new_v4().to_string(),
                            role: "assistant".to_string(),
                            kind: "reasoning".to_string(),
                            payload: serde_json::to_vec(&payload).unwrap_or_default(),
                        })),
                    }))
                    .await;
            }

            // Stream done.
150→            let _ = tx
                .send(Ok(ChatFrame {
                    cursor: bump(),
                    body: Some(chat_frame::Body::Done(StreamDone {
                        conversation_id: conv_id.clone(),
                        total_parts: 1,
                    })),
                }))
                .await;

160→            // Cleanup cancellation registration.
            {
                let mut cancellations = cancellations.lock().await;
                cancellations.remove(&conv_id);
            }
        });

        Ok(Response::new(Box::pin(ReceiverStream::new(rx))))
    }

170→    async fn approve(
        &self,
        request: Request<ApproveRequest>,
    ) -> Result<Response<ApproveResponse>, Status> {
        let req = request.into_inner();
        info!(
            conversation_id = %req.conversation_id,
            tool_call_id = %req.tool_call_id,
            approved = req.approved,
            "ChatService.Approve"
180→        );

        // Deliver the approval decision to the pending tool call.
        let mut approvals = self.approvals.lock().await;
        match approvals.remove(&req.tool_call_id) {
            Some(sender) => {
                let _ = sender.send(req.approved);
                Ok(Response::new(ApproveResponse {
                    success: true,
                    tool_call_id: req.tool_call_id,
190→                    error: None,
                }))
            }
            None => {
                warn!(
                    tool_call_id = %req.tool_call_id,
                    "Approval requested for unknown tool call"
                );
                Ok(Response::new(ApproveResponse {
                    success: false,
200→                    tool_call_id: req.tool_call_id,
                    error: Some("Tool call not found or already completed".to_string()),
                }))
            }
        }
    }

    async fn cancel(
        &self,
        request: Request<CancelRequest>,
210→    ) -> Result<Response<CancelResponse>, Status> {
        let req = request.into_inner();
        info!(
            conversation_id = %req.conversation_id,
            "ChatService.Cancel"
        );

        let mut cancellations = self.cancellations.lock().await;
        match cancellations.remove(&req.conversation_id) {
            Some(cancel_tx) => {
220→                let _ = cancel_tx.send(true);
                Ok(Response::new(CancelResponse {
                    success: true,
                    conversation_id: req.conversation_id,
                }))
            }
            None => {
                warn!(
                    conversation_id = %req.conversation_id,
                    "Cancel requested for unknown conversation"
230→                );
                Ok(Response::new(CancelResponse {
                    success: false,
                    conversation_id: req.conversation_id,
                }))
            }
        }
    }
}

1→// ChatService — gRPC façade for the control-plane chatbot.
//
// The chatbot is a delegator, not an executor. It plans, suggests, coordinates,
// and orchestrates — but always delegates execution to agents. Forced tool
// calling is mandatory: even user-facing responses are emitted as tool calls.
//
// threetched owns LLM provider/model routing (OD-28). SendRequest carries
// the provider/model selection from threetched's state; the server does not
// make routing decisions.
10→//
// Wire vocabulary mirrors AI SDK UIMessage part kinds so renderers stay
// portable, but the producer is our own runtime — no AI SDK provider library.

syntax = "proto3";

package op_chat.chat;

// ============================================================================
// CHAT SERVICE
20→// ============================================================================

service ChatService {
  // Stream a chat completion. Returns a stream of ChatFrame events.
  // The chatbot delegates to agents via forced tool calls; it never executes
  // backplane operations directly.
  rpc Send(SendRequest) returns (stream ChatFrame);

  // Approve a tool call that requires operator confirmation.
  // The chatbot is a delegator — approval gates agent delegation, not direct
30→  // execution.
  rpc Approve(ApproveRequest) returns (ApproveResponse);

  // Cancel an in-flight chat stream.
  rpc Cancel(CancelRequest) returns (CancelResponse);
}

// ============================================================================
// REQUESTS
// ============================================================================
40→
message SendRequest {
  string conversation_id = 1;   // Groups episodes into task chains (threaded)
  bytes  ui_messages = 2;       // JSON-encoded UIMessage[] (AI SDK shape)
  optional string persona_id = 3;
  string provider = 4;          // Native threetched-selected provider (OD-28)
  string model = 5;             // Native threetched-selected model (OD-28)
  optional uint64 resume_cursor = 6;  // Resume from last known cursor on reconnect
}

50→message ApproveRequest {
  string conversation_id = 1;
  string tool_call_id = 2;      // The tool call to approve
  bool approved = 3;            // true = proceed, false = reject
  optional string operator_note = 4;  // Optional reason for rejection
}

message CancelRequest {
  string conversation_id = 1;
}
60→
// ============================================================================
// STREAM FRAMES
// ============================================================================

message ChatFrame {
  uint64 cursor = 1;            // Monotonically increasing; out-of-order = protocol error
  oneof body {
    UIMessagePart part = 2;     // Streamed part (text/tool-call/tool-result/reasoning)
    StreamError   error = 3;
70→    Heartbeat     heartbeat = 4;
    StreamDone    done = 5;
    ApprovalRequired approval = 6;  // Server requests operator approval for a tool call
  }
}

message UIMessagePart {
  string message_id = 1;
  string role = 2;              // "assistant" | "tool" | "system"
  string kind = 3;              // "text" | "tool-call" | "tool-result" | "reasoning"
80→  bytes  payload = 4;           // JSON bytes matching the AI SDK part shape
}

message ApprovalRequired {
  string tool_call_id = 1;
  string tool_name = 2;
  bytes  tool_input = 3;        // JSON bytes of the tool call arguments
  string description = 4;       // Human-readable description of what the tool will do
}

90→message StreamError {
  string code = 1;              // Machine-readable error code
  string message = 2;           // Human-readable error message
  bool retryable = 3;           // Whether the client should retry
  optional uint32 retry_after_ms = 4;
}

message Heartbeat {
  uint64 server_time_ms = 1;
}
100→
message StreamDone {
  string conversation_id = 1;
  uint64 total_parts = 2;
}

// ============================================================================
// RESPONSES
// ============================================================================

110→message ApproveResponse {
  bool success = 1;
  string tool_call_id = 2;
  optional string error = 3;
}

message CancelResponse {
  bool success = 1;
